//! The Simplicity programs an accumulator batch is spent by, pruned, as
//! sequentia-contracts publishes them: `templates/arca_accumulator/exits.json`
//! (`arca/accumulator-1`) and `templates/arca_accumulator_2/paths.json`
//! (`arca/accumulator-2`). Each pruned program is a constant, whatever the
//! batch, the slot, the input index or the key that signs, so a spend is built
//! with no compiler. Copied byte for byte; the regtest tests spend them on the
//! node.

/// The commitment root of `arca/accumulator-1`.
pub const ACCUMULATOR_CMR: &str = "9b6467a1f9d787f6e93ac2422194e61fc56638db63735c6f24ba2c7a86bc0b96";

/// `arca/accumulator-1`, an exit that leaves a rest (2003 bytes).
pub const ACCUMULATOR_EXIT: &str = "";

/// `arca/accumulator-1`, an exit that takes the last of the batch (1877 bytes).
pub const ACCUMULATOR_EXIT_LAST: &str = "";

